preConditionHook:
// THE CHANNEL, one construction shared by the whole lines/channels family
// (decided in slice B01, carried here unchanged):
//   * the BULL channel's trend line runs through the two most recent CONFIRMED
//     swing LOWS and its CHANNEL line through the two most recent confirmed
//     swing HIGHS;
//   * the BEAR channel is the mirror -- trend line across the HIGHS, channel
//     line across the LOWS.
// The two lines are deliberately NOT parallel; a parallel channel has constant
// width, under which ChannelWidthConvergence could never fire.
//
// The pivot scan is INLINED rather than reaching into SwingHigh.json -- rules
// in this corpus never reference each other -- and mirrors the EL twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the pivotStrength OLDER bars, STRICTLY ABOVE the
// pivotStrength NEWER bars -- so a flat top yields exactly one pivot, the later
// of the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar,
// so the strict half is the k < j loop. The confirmation lag is exactly
// pivotStrength bars, never 0 or 1. pivotLookback is EL's Length (offsets
// 0..pivotLookback-1 inclusive) and the neighbourhood test reaches pivotStrength
// bars PAST the window, so the deepest index the scan touches is
// pivotLookback - 1 + pivotStrength. A window with no pivot returns the -1
// SENTINEL, guarded below. Occurrence 3+ is UNMEASURED and never asked for. The
// comparisons carry the 2.22e-12 relational tolerance, hence el_gt / el_ge. The
// low side's tie sense is the mirror of the measured high-side rule. No
// WFSafe_SwingHigh exists, so plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt: the pure two-point line anchored at the FIRST
// pair, Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) * Slope.
// Bars-ago convention, so the OLDER pivot (LARGER bars-ago) is P1/B1, the
// zero-drift spelling. Bar1 = Bar2 silently returns 0.0, so B1 != B2 is
// guarded. The slope is hoisted out of the per-target arithmetic where the EL
// twin recomputes it inside each TLValue call; identical doubles, same line.
//
// THIS RULE: take profit where the channel says the move should stall. A LONG
// is closed when the bar's high reaches the channel line ABOVE (the line
// through the swing highs); a SHORT when the low reaches the line BELOW. Three
// merged framings collapse to one rule because they differ only in which side
// the trade was on: T15-14 is the with-trend long taking profit at the top of
// its own bull channel, T15-35 the countertrend long out of a failed breakout
// targeting the OPPOSITE side, R10-03 the line as a magnet with no trade.
//
// touchTolAtr defaults to 0 (T15-14's plain 'reaches the line'); a small
// positive tolerance takes profit just SHORT of the line, which is what
// Brooks's 'rallies up to that line' implies. It is an ATR fraction rather than
// a tick count because the engine exposes no tick size to strategies.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)pivotStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
loNow = 0.0;
hiNow = 0.0;
if (haveLoLine) {
    loSlope = (loP2 - loP1) / (loB2 - loB1);
    loNow = loP1 + (0.0 - loB1) * loSlope;
}
if (haveHiLine) {
    hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
    hiNow = hiP1 + (0.0 - hiB1) * hiSlope;
}
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget. Seeded with a full sum on the first calculated bar or when
// the length changes, and updated thereafter as TWO statements -- EL evaluates
// S[1] + in - out left to right, and folding it to S += in - out rounds
// differently. The local counter is atrLen; atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
